package com.orderflow.payment;
import com.orderflow.contracts.Events.*;import jakarta.persistence.*;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import java.util.Optional;
@SpringBootApplication public class PaymentApplication{public static void main(String[]a){SpringApplication.run(PaymentApplication.class,a);}@Bean Jackson2JsonMessageConverter json(){return new Jackson2JsonMessageConverter();}@Bean TopicExchange events(){return new TopicExchange("orderflow.events",true,false);}@Bean TopicExchange deadLetters(){return new TopicExchange("orderflow.dlx",true,false);}@Bean Queue paymentDeadLetter(){return QueueBuilder.durable("payment.dead-letter").build();}@Bean Binding paymentDlq(Queue paymentDeadLetter,TopicExchange deadLetters){return BindingBuilder.bind(paymentDeadLetter).to(deadLetters).with("#");}@Bean Queue inventory(){return QueueBuilder.durable("payment.inventory-reserved").deadLetterExchange("orderflow.dlx").build();}@Bean Queue refunds(){return QueueBuilder.durable("payment.refunds").deadLetterExchange("orderflow.dlx").build();}@Bean Binding b1(Queue inventory,TopicExchange events){return BindingBuilder.bind(inventory).to(events).with("inventory.reserved");}@Bean Binding b2(Queue refunds,TopicExchange events){return BindingBuilder.bind(refunds).to(events).with("refund.initiated");}}
@Entity@Table(name="payments",schema="payment")class Payment{@Id UUID id;@Column(name="order_id",unique=true)UUID orderId;String status;BigDecimal amount;@Column(name="idempotency_key",unique=true)String idempotencyKey;@Column(name="created_at")Instant createdAt;protected Payment(){}Payment(UUID o,String key,BigDecimal amount){id=UUID.randomUUID();orderId=o;idempotencyKey=key;this.amount=amount;createdAt=Instant.now();status="PENDING";}}
@Entity@Table(name="refunds",schema="payment")class Refund{@Id UUID id;@Column(name="payment_id")UUID paymentId;String status;@Column(name="created_at")Instant createdAt;protected Refund(){}Refund(UUID p){id=UUID.randomUUID();paymentId=p;status="SUCCEEDED";createdAt=Instant.now();}}
@Entity@Table(name="processed_events",schema="payment")class Seen{@Id@Column(name="event_id")UUID id;@Column(name="processed_at")Instant at=Instant.now();protected Seen(){}Seen(UUID i){id=i;}}
interface PaymentRepo extends JpaRepository<Payment,UUID>{Optional<Payment>findByOrderId(UUID o);}interface RefundRepo extends JpaRepository<Refund,UUID>{}interface SeenRepo extends JpaRepository<Seen,UUID>{}
@Service class PaymentService{private final PaymentRepo payments;private final RefundRepo refunds;private final SeenRepo seen;private final RabbitTemplate rabbit;private final double failureRate;PaymentService(PaymentRepo p,RefundRepo r,SeenRepo s,RabbitTemplate t,@Value("${payment.failure-rate}")double f){payments=p;refunds=r;seen=s;rabbit=t;failureRate=f;}@Transactional@RabbitListener(queues="payment.inventory-reserved")public void process(InventoryReserved e){if(seen.existsById(e.eventId()))return;Payment p=payments.findByOrderId(e.orderId()).orElseGet(()->new Payment(e.orderId(),e.orderId().toString(),e.total()));boolean fail=(Math.floorMod(e.orderId().hashCode(),1000)/1000.0)<failureRate;p.status=fail?"FAILED":"SUCCEEDED";payments.save(p);seen.save(new Seen(e.eventId()));if(fail)rabbit.convertAndSend("orderflow.events","payment.failed",new PaymentFailed(UUID.randomUUID(),e.orderId(),"simulated payment decline",Instant.now()));else rabbit.convertAndSend("orderflow.events","payment.succeeded",new PaymentSucceeded(UUID.randomUUID(),e.orderId(),p.id,Instant.now()));}@Transactional@RabbitListener(queues="payment.refunds")public void refund(RefundInitiated e){if(seen.existsById(e.eventId()))return;refunds.save(new Refund(e.paymentId()));seen.save(new Seen(e.eventId()));}}
